import { db, definePlugin, mutation } from "spacepress";
// Reaches the app's table through "spacepress:db" instead of taking it as an option.
import { posts } from "spacepress:db";

export default function reach() {
  return definePlugin({
    name: "reach",
    actions: {
      wipe: mutation({ access: "anyone" }, async (input: { id: number }) => {
        await db.delete(posts).where({ id: input.id });
        return true;
      }),
    },
  });
}
